const owner = "vijaykadiyala77-hue";
const repo = "n8n-coding-agent";

// Token is fetched from n8n environment variable or hardcoded for development
const token = process.env.GITHUB_TOKEN || "YOUR_GITHUB_TOKEN";

let args;
try {
  args = JSON.parse(query);
} catch(e) {
  return "Error: Tool requires a JSON argument. E.g. {\"action\": \"read\", \"path\": \"filename\"}";
}

const headers = {
  "Authorization": `token ${token}`,
  "Accept": "application/vnd.github.v3+json",
  "User-Agent": "n8n-coding-agent"
};

const baseUrl = `https://api.github.com/repos/${owner}/${repo}/contents`;

async function githubRequest(url, method = "GET", body = null) {
  const options = {
    method,
    headers,
  };
  if (body) {
    options.headers["Content-Type"] = "application/json";
    options.body = JSON.stringify(body);
  }
  const res = await fetch(url, options);
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`GitHub API Error (${res.status}): ${errText}`);
  }
  return await res.json();
}

try {
  if (args.action === "read") {
    const url = `${baseUrl}/${args.path}`;
    const data = await githubRequest(url, "GET");
    if (data.type === "file") {
      const content = Buffer.from(data.content, "base64").toString("utf-8");
      return content;
    } else {
      return `Error: ${args.path} is a directory. Use list action instead.`;
    }
  } 

  else if (args.action === "write") {
    const url = `${baseUrl}/${args.path}`;
    let sha = null;
    try {
      const existing = await githubRequest(url, "GET");
      if (existing && existing.sha) {
        sha = existing.sha;
      }
    } catch(e) {
      // File does not exist yet
    }

    const body = {
      message: args.commitMessage || `Update ${args.path} via AI Coding Agent`,
      content: Buffer.from(args.content).toString("base64")
    };
    if (sha) {
      body.sha = sha;
    }

    const data = await githubRequest(url, "PUT", body);
    return `Successfully wrote file ${args.path}. Commit SHA: ${data.commit.sha}`;
  } 

  else if (args.action === "list") {
    const url = `${baseUrl}/${args.path || ""}`;
    const data = await githubRequest(url, "GET");
    if (Array.isArray(data)) {
      const items = data.map(item => `${item.type === "dir" ? "[DIR]" : "[FILE]"} ${item.path}`).join("\n");
      return items || "Directory is empty";
    } else {
      return `Error: Path is not a directory.`;
    }
  } 

  else {
    return `Unknown action: ${args.action}. Supported actions: read, write, list.`;
  }
} catch (error) {
  return `Error executing github_actions tool: ${error.message}`;
}
